package device_pairing

import (
	"database/sql"
	"fmt"
	"time"

	"server/internal/db"
)

// DevicePairing represents a pairing code generated by a carepartner device
type DevicePairing struct {
	ID            int       `json:"id"`
	CarepartnerID int       `json:"carepartner_id"`
	PairingCode   string    `json:"pairing_code"`
	ExpiresAt     time.Time `json:"expires_at"`
	Paired        bool      `json:"paired"`
}

// ─────────────────────────────────────────────
// CREATE
// ─────────────────────────────────────────────

// CreateDevicePairing inserts a new pairing record
func CreateDevicePairing(db *sql.DB, p *DevicePairing) error {
	query := `
		INSERT INTO "DevicePairing" (carepartner_id, pairing_code, expires_at, paired)
		VALUES ($1, $2, $3, $4)
		RETURNING id;
	`

	return db.QueryRow(
		query,
		p.CarepartnerID,
		p.PairingCode,
		p.ExpiresAt,
		p.Paired,
	).Scan(&p.ID)
}

//
// READ
//

func GetDevicePairingByID(db *sql.DB, id int) (*DevicePairing, error) {
	query := `
		SELECT id, carepartner_id, pairing_code, expires_at, paired
		FROM "DevicePairing"
		WHERE id = $1;
	`

	p := &DevicePairing{}

	err := db.QueryRow(query, id).Scan(
		&p.ID,
		&p.CarepartnerID,
		&p.PairingCode,
		&p.ExpiresAt,
		&p.Paired,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}

	return p, nil
}

func GetDevicePairingByCode(db *sql.DB, code string) (*DevicePairing, error) {
	query := `
		SELECT id, carepartner_id, pairing_code, expires_at, paired
		FROM "DevicePairing"
		WHERE pairing_code = $1;
	`

	p := &DevicePairing{}

	err := db.QueryRow(query, code).Scan(
		&p.ID,
		&p.CarepartnerID,
		&p.PairingCode,
		&p.ExpiresAt,
		&p.Paired,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}

	return p, nil
}

func GetDevicePairings(db *sql.DB) ([]DevicePairing, error) {
	query := `
		SELECT id, carepartner_id, pairing_code, expires_at, paired
		FROM "DevicePairing";
	`

	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var list []DevicePairing

	for rows.Next() {
		var p DevicePairing

		if err := rows.Scan(
			&p.ID,
			&p.CarepartnerID,
			&p.PairingCode,
			&p.ExpiresAt,
			&p.Paired,
		); err != nil {
			return nil, err
		}

		list = append(list, p)
	}

	return list, nil
}

//
// UPDATE
//

func UpdateDevicePairing(db *sql.DB, p *DevicePairing) error {
	query := `
		UPDATE "DevicePairing"
		SET carepartner_id = $1,
		    pairing_code = $2,
		    expires_at = $3,
		    paired = $4
		WHERE id = $5;
	`

	res, err := db.Exec(
		query,
		p.CarepartnerID,
		p.PairingCode,
		p.ExpiresAt,
		p.Paired,
		p.ID,
	)

	if err != nil {
		return err
	}

	count, _ := res.RowsAffected()
	if count == 0 {
		return fmt.Errorf("no pairing found with id %d", p.ID)
	}

	return nil
}

//
// DELETE
//

func DeleteDevicePairing(db *sql.DB, id int) error {
	query := `DELETE FROM "DevicePairing" WHERE id = $1;`

	res, err := db.Exec(query, id)
	if err != nil {
		return err
	}

	count, _ := res.RowsAffected()
	if count == 0 {
		return fmt.Errorf("no pairing found with id %d", id)
	}

	return nil
}

// Delete the pairing codes of every carepartner paired with a caregiver, so their
// devices report unpaired; works with a *sql.DB or a *sql.Tx
func DeletePairingsForCaregiver(exec db.Execer, caregiverID int) error {
	query := `
		DELETE FROM "DevicePairing"
		WHERE carepartner_id IN (SELECT id FROM "Carepartner" WHERE caregiver_id = $1);
	`

	_, err := exec.Exec(query, caregiverID)
	return err
}
